from calendar import monthrange
from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    tokens = rule.split()
    frequency = tokens[0]
    interval = int(tokens[1])

    if frequency == "DAILY":
        return [
            (start_date + timedelta(days=i * interval)).isoformat()
            for i in range(count)
        ]

    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }
    result = []

    if frequency == "WEEKLY":
        selected = sorted(weekdays[code] for code in tokens[2].split(","))
        monday = start_date - timedelta(days=start_date.weekday())

        while True:
            for weekday in selected:
                candidate = monday + timedelta(days=weekday)
                if candidate >= start_date:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=interval)

    if frequency == "MONTHLY":
        month_index = start_date.year * 12 + start_date.month - 1
        number = int(tokens[2])
        weekday = weekdays[tokens[3]] if len(tokens) == 4 else None

        while len(result) < count:
            year, zero_based_month = divmod(month_index, 12)
            month = zero_based_month + 1
            first_weekday, last_day = monthrange(year, month)

            if weekday is None:
                day = last_day if number == -1 else number
            elif number == -1:
                last_weekday = (first_weekday + last_day - 1) % 7
                day = last_day - (last_weekday - weekday) % 7
            else:
                day = 1 + (weekday - first_weekday) % 7 + 7 * (number - 1)

            if 1 <= day <= last_day:
                candidate = date(year, month, day)
                if candidate >= start_date:
                    result.append(candidate.isoformat())

            month_index += interval

        return result

    month, day = map(int, tokens[2].split("-"))
    year = start_date.year

    while len(result) < count:
        if day <= monthrange(year, month)[1]:
            candidate = date(year, month, day)
            if candidate >= start_date:
                result.append(candidate.isoformat())
        year += interval

    return result
